local modgui = require("modgui")
local logger = modgui.getRightLoggerModule()
local log = logger.new("wireless.ap.security", 2)
local register = register;

local wireless_ap_security_ = {
  objectType = {
    name = "rpc.wireless.ap.@.security.",
    access = "readOnly",
    minEntries = 1,
    maxEntries = 1,
    parameters = {
        mode = {
            access = "readWrite",
            type = "string",
        },
        wep_key = {
            access = "readWrite",
            type = "string",
        },
        wpa_psk_passphrase = {
            access = "readWrite",
            type = "string",
        },
        supported_modes = {
            access = "readOnly",
            type = "string",
        },
        pmf = {
            access = "readWrite",
            type = "string",
        },
    },
  }
}

local uci_helper = mapper("ucihelper")
local conn = mapper("ubus").connect()

local function nilToEmptyString(st)
    if st == nil then
        return ""
    else
        return tostring(st)
    end
end

local function getDataForAP(ap)
    local result = conn:call("wireless.accesspoint.security", "get", { name = ap })
    if result == nil then
        -- newer firmwares expose the security parameters through the main
        -- accesspoint object instead of the wireless.accesspoint.security one
        result = conn:call("wireless.accesspoint", "get", { name = ap })
    end
    if result == nil then
        log:error("Cannot retrieve security info for ap " .. ap)
        return {}
    end
    return result[ap] or {}
end

local namemap = {   mode="security_mode",
                    wpa_psk_passphrase="wpa_psk_key"
                }

local default_supported_modes = "none wpa2-psk wpa-wpa2-psk wpa3-psk wpa2-wpa3-psk"

local function getall(mapping, key)
    local apData = getDataForAP(key)
    local sanitizedData = {}
    for k,v in pairs(apData) do
        sanitizedData[k] = nilToEmptyString(v)
    end
    if not sanitizedData.wpa_psk_passphrase or sanitizedData.wpa_psk_passphrase == "" then
        sanitizedData.wpa_psk_passphrase = (sanitizedData.wpa_psk_key and sanitizedData.wpa_psk_key ~= "") and sanitizedData.wpa_psk_key or nilToEmptyString(uci_helper.get_from_uci({config = "wireless", sectionname = key, option = "wpa_psk_key"}))
    end
    if not sanitizedData.mode or sanitizedData.mode == "" then
        sanitizedData.mode = (sanitizedData.security_mode and sanitizedData.security_mode ~= "") and sanitizedData.security_mode or nilToEmptyString(uci_helper.get_from_uci({config = "wireless", sectionname = key, option = "security_mode"}))
    end
    if not sanitizedData.pmf or sanitizedData.pmf == "" then
        sanitizedData.pmf = nilToEmptyString(uci_helper.get_from_uci({config = "wireless", sectionname = key, option = "pmf"}))
    end
    if not sanitizedData.supported_modes or sanitizedData.supported_modes == "" then
        sanitizedData.supported_modes = default_supported_modes
    end
    return sanitizedData
end

local function get(mapping, paramName, key)
    local apData = getDataForAP(key)
    local val = apData[paramName]
    if (val == nil or val == "") and namemap[paramName] then
        val = apData[namemap[paramName]]
    end
    if val == nil or val == "" then
        val = uci_helper.get_from_uci({config = "wireless", sectionname = key, option = namemap[paramName] or paramName})
    end
    if paramName == "supported_modes" and (val == nil or val == "") then
        val = default_supported_modes
    end
    return nilToEmptyString(val)
end
local set = function(mapping, param, value, key)
  if param == "wpa_psk_passphrase" then
    local pskmatch = "^[ -~]+$"
    local preventXssAttack = "<[ -~]+>"
    if #value < 8 or #value > 64 then
      return nil, "The password must be between 8 and 63 characters"
    elseif #value == 64 and not value:match("^[a-fA-F0-9]+$") then
      return nil, "For a length of 64 characters, only numbers and letters from A to F are accepted"
    elseif value:match(preventXssAttack) or not string.match(value, pskmatch) then
      return nil, "The wireless key contains invalid characters, only space, letters, numbers and the following characters !\"#%&()*+,-./:;=?@[\\]^_{|}~'$` are allowed and the characters <> are not allowed to prevent XSS script execution."
    end
  end
  if param == "mode" then
    if value == "wpa3-psk" then
      local wpsVal = uci_helper.get_from_uci({config = "wireless", sectionname = key, option = "wps_state"}) or "1"
      uci_helper.set_on_uci({ config = "system", sectionname = key , option = "last_state"}, wpsVal, commitapply)
      uci_helper.set_on_uci({ config = "wireless", sectionname = key , option = "wps_state"}, "0", commitapply)
      uci_helper.set_on_uci({ config = "wireless", sectionname = key , option = "pmf"}, "required", commitapply)
    elseif value == "wpa2-wpa3-psk" then
      uci_helper.set_on_uci({ config = "wireless", sectionname = key , option = "pmf"}, "optional", commitapply)
      local wpsVal = uci_helper.get_from_uci({ config = "system", sectionname = key, option = "last_state"}) or "1"
      uci_helper.set_on_uci({ config = "wireless", sectionname = key , option = "wps_state"}, wpsVal, commitapply)
    else
      local secMode = uci_helper.get_from_uci({config = "wireless", sectionname = key, option = "security_mode"})
      if secMode ~= value then
        local wpsVal = uci_helper.get_from_uci({ config = "system", sectionname = key, option = "last_state"}) or "1"
        uci_helper.set_on_uci({ config = "wireless", sectionname = key , option = "wps_state"}, wpsVal, commitapply)
      end
      if value == "none" then
        uci_helper.set_on_uci({ config = "wireless", sectionname = key , option = "pmf"}, "disabled", commitapply)
      end
    end
  end
  uci_helper.set_on_uci({ config = "wireless", sectionname = key , option = namemap[param] or param}, value, commitapply)
end

wireless_ap_security_.getall = getall
wireless_ap_security_.get = get
wireless_ap_security_.set = set
wireless_ap_security_.commit = function()
    uci_helper.commit({config = "wireless"})
end
wireless_ap_security_.revert = function()
    uci_helper.revert({config = "wireless"})
end

register(wireless_ap_security_)
